import { revalidateTag } from 'next/cache'
import { getProducts, type Product } from '@/lib/products'

export const dynamic = 'force-static'

export default async function CatalogPage() {
  const products = await getProducts()

  // Inline Server Action: triggers a background refresh of the catalog.
  //
  // `revalidateTag('products', 'max')` uses stale-while-revalidate semantics:
  // it marks the `"products"` tag for a background re-fetch and returns
  // immediately. The action response does NOT block on freshly recomputed
  // data and does NOT force a re-render that waits for it, so the admin can
  // keep working right away. The catalog (and every view sharing the
  // `"products"` tag) becomes up to date shortly after, as the background
  // re-query of `getProducts` completes.
  async function syncCatalog() {
    'use server'
    // In production this is where the upstream ERP/PIM sync job would be
    // kicked off. Because it can touch thousands of SKUs, we deliberately do
    // NOT await the full recompute here; `revalidateTag` schedules the
    // background refresh of the cached catalog so the admin stays responsive.
    revalidateTag('products', 'max')
  }

  return (
    <main style={{ fontFamily: 'system-ui, sans-serif', maxWidth: 900, margin: '0 auto', padding: 24 }}>
      <header style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 16 }}>
        <div>
          <h1 style={{ margin: 0 }}>Product Catalog</h1>
          <p style={{ margin: '4px 0 0', color: '#666' }}>
            Served from cache. Sync pulls the latest pricing, inventory, and
            availability from the ERP/PIM in the background.
          </p>
        </div>

        {/* Regular HTML form invoking the inline Server Action. Works with
            progressive enhancement (submits even before JS hydrates). */}
        <form action={syncCatalog}>
          <button
            type="submit"
            style={{
              padding: '10px 16px',
              fontSize: 14,
              fontWeight: 600,
              border: '1px solid #111',
              background: '#111',
              color: '#fff',
              borderRadius: 6,
              cursor: 'pointer',
            }}
          >
            Sync latest catalog
          </button>
        </form>
      </header>

      <table style={{ width: '100%', marginTop: 24, borderCollapse: 'collapse', textAlign: 'left' }}>
        <thead>
          <tr style={{ borderBottom: '2px solid #eee' }}>
            <th style={{ padding: '8px 12px' }}>ID</th>
            <th style={{ padding: '8px 12px' }}>Name</th>
            <th style={{ padding: '8px 12px', textAlign: 'right' }}>Price</th>
          </tr>
        </thead>
        <tbody>
          {products.map((product: Product) => (
            <tr key={product.id} style={{ borderBottom: '1px solid #f1f1f1' }}>
              <td style={{ padding: '8px 12px' }}>{product.id}</td>
              <td style={{ padding: '8px 12px' }}>{product.name}</td>
              <td style={{ padding: '8px 12px', textAlign: 'right' }}>
                ${product.price.toLocaleString()}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </main>
  )
}

